/**
 * Moves an issue to another project, assigning it the next number of that
 * project. Everything else on the row (status, priority, assignee, estimate,
 * due date, labels, comments, attachments) is untouched by this update.
 */
export async function moveIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  toProjectId: ProjectId,
  toNumber: number,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({
      projectId: toProjectId,
      number: toNumber,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

